const fs = require('fs');
const path = require('path');

const RECOMMENDED_IGNORE = [
  '# Auto-generated by ClaudeCut for Large Repositories',
  '# Dependencies & packages',
  'node_modules/',
  'vendor/',
  '.venv/',
  'venv/',
  'env/',
  '__pycache__/',
  '*.pyc',
  '',
  '# Build outputs & artifacts',
  'dist/',
  'build/',
  'out/',
  '.next/',
  '.nuxt/',
  'coverage/',
  'target/',
  'bin/',
  'obj/',
  '',
  '# Large lockfiles (major cause of context blowup in Claude Code)',
  'package-lock.json',
  'yarn.lock',
  'pnpm-lock.yaml',
  'poetry.lock',
  'Cargo.lock',
  'composer.lock',
  '',
  '# Logs, binaries, assets',
  '*.log',
  '*.sqlite',
  '*.sqlite3',
  '*.db',
  '*.min.js',
  '*.min.css',
  '*.map',
  '*.png',
  '*.jpg',
  '*.jpeg',
  '*.gif',
  '*.svg',
  '*.mp4',
  '*.pdf',
  '*.zip',
  '*.tar.gz'
].join('\n');

function ensureClaudeIgnore(targetDir = process.cwd()) {
  const ignorePath = path.join(targetDir, '.claudeignore');
  if (!fs.existsSync(ignorePath)) {
    fs.writeFileSync(ignorePath, RECOMMENDED_IGNORE, 'utf8');
    return { created: true, path: ignorePath };
  }
  return { created: false, path: ignorePath };
}

module.exports = { ensureClaudeIgnore };
